//! The two generated files: the scheme JSON (one class per line, so a
//! rebuild diffs line by line) and SOURCES.md.

use std::fmt::Write;

use shelfmark_core::scheme::SchemeDoc;

use crate::build::Stats;
use crate::sources::{Lock, Role};

/// The scheme as JSON: header fields pretty-printed, then one class per
/// line.
pub fn scheme_json(doc: &SchemeDoc) -> Result<String, String> {
    let err = |e: serde_json::Error| e.to_string();
    let mut head = doc.clone();
    head.classes.clear();
    let head = serde_json::to_string_pretty(&head).map_err(err)?;
    let head = head
        .trim_end()
        .strip_suffix('}')
        .and_then(|h| h.trim_end().strip_suffix("\"classes\": []"))
        .ok_or("unexpected scheme JSON layout")?;
    let mut out = format!("{head}\"classes\": [\n");
    for (i, c) in doc.classes.iter().enumerate() {
        let sep = if i + 1 < doc.classes.len() { "," } else { "" };
        let _ = writeln!(out, "    {}{sep}", serde_json::to_string(c).map_err(err)?);
    }
    out.push_str("  ]\n}\n");
    Ok(out)
}

/// SOURCES.md: each source's lock entry, the license note and what the
/// build kept and dropped.
pub fn sources_md(lock: &Lock, s: &Stats, doc: &SchemeDoc) -> String {
    let mut o = String::new();
    let _ = write!(
        o,
        "# NAICS scheme: sources\n\n\
         Generated by `src/shelfmark/schemes/naics/builder` (`naics-scheme build`); do not edit by hand.\n\
         `naics.json` is scheme `{name}@{version}` with {n} classes and validates against\n\
         `src/shelfmark/schemas/scheme.schema.json` and `shelfmark_core::scheme::SchemeDoc`.\n\n\
         ## Rebuild\n\n\
         ```sh\n\
         cd src/shelfmark/schemes/naics/builder\n\
         cargo run --release -- fetch --cache /tmp/naics-sources   # network; rewrites sources.lock.json\n\
         cargo run --release -- build --cache /tmp/naics-sources   # offline; deterministic from the lock\n\
         cargo run --release -- check --cache /tmp/naics-sources   # fails if naics.json or SOURCES.md is stale\n\
         ```\n\n\
         `build` refuses any cached file whose sha256 differs from `sources.lock.json`.\n\n\
         ## License\n\n\
         The inputs are the United States edition of NAICS 2022, issued by the Office of Management\n\
         and Budget and published by the US Census Bureau. As works of the US government they are\n\
         not subject to copyright in the United States (17 U.S.C. 105), so `naics.json` may ship\n\
         inside an open-source binary or package; no downloader is needed. Credit the source as\n\
         \"Source: U.S. Census Bureau, 2022 NAICS\". The Canadian and Mexican editions (Statistics\n\
         Canada, INEGI) carry their own terms and are not used. The derived `naics.json` keeps the\n\
         titles and index entries verbatim apart from collapsing runs of whitespace.\n\n\
         ## Sources\n\n",
        name = doc.name,
        version = doc.version,
        n = doc.classes.len(),
    );
    let roles = [
        (Role::Codes, "2022 NAICS 2-6 digit codes and US titles"),
        (
            Role::Index,
            "2022 NAICS index file: entries and their 6-digit industries",
        ),
    ];
    for (role, what) in roles {
        let _ = writeln!(
            o,
            "### {what}\n\n| file | fetched | bytes | sha256 |\n|---|---|---|---|"
        );
        for l in lock.sources.iter().filter(|l| l.role == role) {
            let _ = writeln!(
                o,
                "| [{}]({}) | {} | {} | `{}` |",
                l.file, l.url, l.fetched, l.bytes, l.sha256
            );
        }
        o.push('\n');
    }
    let [sectors, subsectors, groups, industries, national] = s.by_level;
    let _ = write!(
        o,
        "## What the build kept\n\n\
         - sectors: {sectors} (spans: {spans})\n\
         - subsectors (3 digits): {subsectors}\n\
         - industry groups (4 digits): {groups}\n\
         - NAICS industries (5 digits): {industries}\n\
         - national industries (6 digits): {national}\n\
         - `naics-index` vocabulary terms: {terms} (from {rows} index rows)\n\
         - LCC or LCSH links: none; NAICS publishes no crosswalk to them\n\n\
         ## What the build dropped\n\n\
         - `******` index rows (\"see\" cross-references with no code): {xref}\n\
         - index terms repeating the industry's own title: {echoes}\n\
         - index terms repeating another term on the same industry: {dups}\n\
         - index rows naming a code not in the codes table: {unknown}\n\
         - 6-digit industries with no index entry: {bare}\n",
        spans = s.sector_spans.join(", "),
        terms = s.index_terms,
        rows = s.index_rows,
        xref = s.cross_references,
        echoes = s.echoes,
        dups = s.duplicates,
        unknown = list(&s.unknown_codes),
        bare = list(&s.industries_without_terms),
    );
    o
}

fn list(items: &[String]) -> String {
    if items.is_empty() {
        "none".to_string()
    } else {
        format!("{} ({})", items.len(), items.join(", "))
    }
}
